    </div>
  </StoryContainer>
);

export const Inline = () => (
  <StoryContainer>
    <div style={{ padding: "5px" }}>
      <Tooltip
        content={text(
          "Text",
          "should be centered around inline element",
        )}
      >
        <span style={{ backgroundColor: "yellow", padding: "5px" }}>I'm an inline element</span>
      </Tooltip>
    </div>
    <div style={{ padding: "5px" }}>
      <Tooltip
        content={text(
          "Text",
          "should be centered around block element",
        )}
      >
        <div style={{ backgroundColor: "yellow", padding: "5px" }}>I'm a block element</div>
      </Tooltip>
    </div>
  </StoryContainer>
);

import React, {
  FunctionComponent,
  ReactElement,
  useEffect,
  useState,
} from "react";
import { usePopper } from "react-popper";
import classNames from "classnames";
import css from "./Tooltip.module.scss";

export type TooltipPosition =
  | "left"
  | "left-start"
  | "left-end"
  | "right"
  | "right-start"
  | "right-end"
  | "top"
  | "top-start"
  | "top-end"
  | "bottom"
  | "bottom-start"
  | "bottom-end";

export type TooltipStyle = "default" | "light" | "dark" | "tableTitle";

export interface TooltipProps {
  placement?: TooltipPosition;
  style?: TooltipStyle;
  content: ReactElement | string;
  visible?: boolean;
}

export const Tooltip: FunctionComponent<TooltipProps> = ({
  placement = "bottom",
  style = "default",
  children,
  content,
  visible = false,
}) => {
  const [referenceElement, setReferenceElement] = useState(null);
  const [popperElement, setPopperElement] = useState(null);
  const [arrowElement, setArrowElement] = useState(null);

  const { styles, attributes } = usePopper(referenceElement, popperElement, {
    placement,
    modifiers: [
      { name: "arrow", options: { element: arrowElement } },
      { name: "offset", options: { offset: [0, -25] } },
      {
        name: "computeStyles",
        options: {
          gpuAcceleration: false, // true by default
        },
      },
    ],
  });

  useEffect(() => {
    const onScroll = () => {
      popperElement?.removeAttribute("data-show");
    };
    document.addEventListener("scroll", onScroll, true);
    return () => document.removeEventListener("scroll", onScroll);
  }, [popperElement]);

  if (!content) {
    return <>{children}</>;
  }

  const classnames = classNames(css[style], css.Tooltip);
  if (visible && popperElement) {
    popperElement.setAttribute("data-show", "");
  }

  const wrappedChildren = React.Children.map(children, (child) => {
    return React.cloneElement(
      typeof children === "string" ? <>{child}</> : (child as ReactElement),
    );
  });

  return (
    <div
      ref={setReferenceElement}
      onMouseOver={() => {
        popperElement.setAttribute("data-show", "");
      }}
      onMouseLeave={() => {
        popperElement.removeAttribute("data-show");
      }}
    >
      {wrappedChildren}

      <div
        className={classnames}
        ref={setPopperElement}
        style={styles.popper}
        data-jest="tooltip"
        onMouseLeave={() => {
          if (visible) return;
          popperElement.removeAttribute("data-show");
        }}
        onClick={(e) => {
          e.stopPropagation();
        }}
        {...attributes.popper}
      >
        <div className={css.content}>
          <div
            className={css.arrow}
            ref={setArrowElement}
            style={styles.arrow}
          />
          <div className={css.arrowInner} style={styles.arrow} />
          <div className={css.text}>{content}</div>
        </div>
      </div>
    </div>
  );
};

@import "../styles/tokens.scss";

//
// Tooltips
// --------------------------------------------------

$border-radius-base: 3px;
$tooltip-border-width: 1px;
$tooltip-shadow-width: 0px;

$tooltip-arrow-width: 10px;
$tooltip-arrow-half-width: 5px;

// Base class
.Tooltip {
  all: initial;
  visibility: hidden;
  opacity: 0;
  position: absolute;
  z-index: -1;
  transition: opacity 0.1s, visibility 0.1s, z-index 0.1s;
  min-width: 300px;
  max-width: 500px;
  pointer-events: none;

  p,
  pre,
  code {
    all: initial;
    font-family: $type-family-ui;
    font-size: $type-size-font-medium;
  }

  & > .content {
    @include crl-depth(1);
    padding: 8px 10px;
    margin: 30px;
    text-align: left;
    text-decoration: none;
    border-radius: $border-radius-base;
    border: $tooltip-border-width solid;
    position: relative;
    overflow: visible;
    font-family: $type-family-ui;
    pointer-events: all;
  }

  &[data-show] {
    visibility: visible;
    opacity: 1;
    z-index: 9999;
    transition: opacity 0.1s, visibility 0.1s, z-index 0.1s;
  }

  .arrow,
  .arrowInner {
    position: absolute;
    width: $tooltip-arrow-width;
    height: $tooltip-arrow-width;
    overflow: visible;
    &:before {
      content: "";
      position: absolute;
      width: $tooltip-arrow-width;
      height: $tooltip-arrow-width;
      transform: rotate(45deg);
      border: $tooltip-border-width solid;
    }
  }

  .arrow:before {
    @include crl-depth(1);
    z-index: -5;
  }

  .arrowInner:before {
    z-index: 5;
  }

  &[data-popper-placement^="top"] .arrow,
  &[data-popper-placement^="top"] .arrowInner {
    bottom: -$tooltip-arrow-half-width;
  }

  &[data-popper-placement^="bottom"] .arrow,
  &[data-popper-placement^="bottom"] .arrowInner {
    top: -$tooltip-arrow-half-width;
  }

  &[data-popper-placement^="left"] .arrow,
  &[data-popper-placement^="left"] .arrowInner {
    right: -$tooltip-arrow-half-width;
  }

  &[data-popper-placement^="right"] .arrow,
  &[data-popper-placement^="right"] .arrowInner {
    left: -$tooltip-arrow-half-width;
  }
}

@mixin crl-tooltip-style($bg, $border, $color) {
  .content {
    border-color: $border;
    background-color: $bg;
    color: $color;
    p,
    pre,
    code {
      color: $color;
    }
  }
  .arrow:before {
    border-color: $border;
    background-color: $bg;
  }
  .arrowInner:before {
    background-color: $bg;
    border-color: transparent;
  }
}

//
// Default style
// --------------------------------------------------
.default {
  @include crl-tooltip-style(
    $color-core-neutral-6,
    $color-core-neutral-6,
    $color-base-white
  );
}
//
// Dark style
// --------------------------------------------------
.dark {
  @include crl-tooltip-style(
    $color-base-black,
    $color-base-black,
    $color-base-white
  );
}

//
// TableTitle
// --------------------------------------------------
.tableTitle {
  @include crl-tooltip-style(
    $color-core-neutral-6,
    $color-core-neutral-6,
    $color-base-white
  );
  .text {
    &,
    p,
    a {
      font-weight: 600;
      font-size: $type-size-font-small;
      line-height: $type-size-line-height-small;
      letter-spacing: 0.3px;
      color: $color-intent-neutral-0;
    }

    a {
      text-decoration: underline;
      &:hover {
        opacity: 0.7;
        color: $color-intent-neutral-0;
      }
    }
    code {
      font-family: $type-family-code;
      font-size: $type-size-font-small;
      line-height: $type-size-line-height-regular;
      color: $color-intent-neutral-8;
      background: $color-intent-neutral-0;
      border-radius: 3px;
      padding: 2px 5px;
    }
  }
}

//
// Light style
// --------------------------------------------------
.light {
  @include crl-tooltip-style(
    $color-base-white,
    $color-core-neutral-2,
    $color-font-3
  );
}

@import "@cockroachlabs/design-tokens/dist/web/_tokens.scss";

/**
 Variables
*/
// This variable reflects the base gutter value
// specified by our design system.
$crl-gutters: 8px;
$crl-border-radius: 3px;
$crl-input-height: 40px;
$crl-input-height-small: 24px;
$crl-transition-duration: 0.15s;

/**
 Mixins
*/
@mixin crl-depth($n_: 1, $color_: $color-core-blue-5) {
  /**
      Desc:
        This mixin sets the `box-shadow` property
        to reflect the depth layers outlined in the
        CRL design system.

      Example usage:
        `@include depth(3);`
    */
  $depth-1: 0 1px 5px 0px rgba($color_, 0.17);
  $depth-2: 0 6px 15px 0px rgba($color_, 0.17);
  $depth-3: 0 9px 20px 0px rgba($color_, 0.27);
  $depth-4: 0 10px 40px 0px rgba($color_, 0.37);

  @if $n_ == 1 {
    -webkit-box-shadow: $depth-1;
    -moz-box-shadow: $depth-1;
    box-shadow: $depth-1;
  } @else if $n_ == 2 {
    -webkit-box-shadow: $depth-2;
    -moz-box-shadow: $depth-2;
    box-shadow: $depth-2;
  } @else if $n_ == 3 {
    -webkit-box-shadow: $depth-3;
    -moz-box-shadow: $depth-3;
    box-shadow: $depth-3;
  } @else if $n_ == 4 {
    -webkit-box-shadow: $depth-4;
    -moz-box-shadow: $depth-4;
    box-shadow: $depth-4;
  } @else {
    box-shadow: none;
  }
}

@mixin crl-transition($props_...) {
  /**
    Desc:
      Helper for maintaining consistent transitions.
    Example usage:
      ```
      .my-css-class {
        @include crl-transition(color, border-color, height);
      }
      ```
  */
  transition-property: $props_;
  transition-duration: $crl-transition-duration;
  transition-timing-function: ease-in-out;
}

@mixin crl-box-shadow($offset_h_, $offset_v_, $blur_, $spread_, $color_) {
  /**
    Desc:
      Helper for cross-browser box-shadows.
    Example usage:
      ```
      .my-css-class {
        @include crl-box-shadows(0, 2px, 4px, 0, $crl-blue-5);
      }
      ```
  */
  -webkit-box-shadow: $offset_h_ $offset_v_ $blur_ $spread_ $color_;
  -moz-box-shadow: $offset_h_ $offset_v_ $blur_ $spread_ $color_;
  box-shadow: $offset_h_ $offset_v_ $blur_ $spread_ $color_;
}

@mixin firefox-only {
  @at-root {
    @-moz-document url-prefix() {
      & {
        @content;
      }
    }
  }
}

/**
 Variables
*/
// This variable reflects the base gutter value
// specified by our design system.
$crl-gutters: 8px;

/**
 Functions
*/
@function crl-lighten($color) {
  /**
    Desc:
      Helper for consistent lightening of default tone,
      for example in lightening a button in a disabled state.

    Example usage:
      ```
      .my-css-class {
        background-color: crl-lighten($crl-base-green);
      }
      ```
  */
  @return mix(white, $color, 95%);
}

@function crl-darken($color) {
  /**
    Desc:
      Helper for consistent darkening of default tone,
      for example in darkening a button in a hovered or active state.

    Example usage:
      ```
      .my-css-class {
        background-color: crl-darken($crl-base-green);
      }
      ```
  */
  @return mix(black, $color, 10%);
}

@function crl-gutters($n_: 1) {
  /**
    Desc:
      Use this function when spacing elements to preserve
      consistent spacing in multiples of our gutter value
      established in the CRL design system.

      Only use explict values (e.g. `margin: 5px;`) in CSS
      when setting a one-off value that is used for fine-tuning
      an element position (e.g. such as aligning an SVG icon).

    Example usage:
      ```
      .my-css-class {
        padding-top: crl-gutters(3);
        margin-bottom: crl-gutters(1);
      }
      ```
  */
  @if $n_ {
    @return $n_ * $crl-gutters;
  } @else {
    @return 0;
  }
}
